1	// Half-even rounding to cents.
2	function roundCents(x) {
3	  const n = x * 100;
4	  const f = Math.floor(n);
5	  const d = n - f;
6	  if (Math.abs(d - 0.5) < 1e-9) return (f % 2 === 0 ? f : f + 1) / 100;
7	  return Math.round(n) / 100;
8	}
9	module.exports = { roundCents };
